@Test
public void testSendMessageToDingDing() throws Exception {
    final int times = 3;
    List<ConnectRecord> records = new ArrayList<>();
    for (int i = 0; i < times; i++) {
        ConnectRecord connectRecord = new ConnectRecord(null, null, System.currentTimeMillis(), "Hello, EventMesh!".getBytes(StandardCharsets.UTF_8));
        connectRecord.addExtension(ConnectRecordExtensionKeys.DINGTALK_TEMPLATE_TYPE, DingDingMessageTemplateType.PLAIN_TEXT.getTemplateType());
        records.add(connectRecord);
    }
    connector.put(records);
    verify(sendMessageClient, times(times)).orgGroupSendWithOptions(any(), any(), any());
    // verify for access token cache.
    verify(authClient, times(1)).getAccessToken(any());
}

